"""SQL questions. Each question carries its reference query; the build runs it to
validate it, and the website runs it again in the browser to check a student's
query result against it.

ordered=True means the row order is part of the answer (the prompt always gives
a full tie-break so the expected order is unique).
"""

def q(id, file, course, topics, minutes, prompt, sql, ordered=False):
    return dict(id=id, file=file, subject="SQL", course=course, topics=topics,
                minutes=minutes, prompt=prompt, check=dict(type="sql", sql=sql.strip(), ordered=ordered))


